import Foundation
import GRDB
import Testing
import FlotsamBase
import FlotsamPayload
@testable import FlotsamStorage
@testable import FlotsamCapture

// TASK-498 step 3, FRD-001 FR-001-25 and FR-001-04 gate 3 (AC-001-25: a concealed copy becomes a secure row and no
// plaintext of it reaches the database, its WAL or the log; AC-001-04: Transient and AutoGenerated stay rejected, and
// Concealed is rejected when there is no vault to seal it). The real SecureClipVault (only its Keychain is a fake),
// ClipboardCapture, IngestWorker, IngestActor and an on-disk FlotsamDatabase are the collaborators; the pasteboard,
// source-app lookup, presenter, clock and log sink are the existing contract fakes. Expected values are literals.

private let concealed = PasteboardMarkers.concealed
private let marker = "SECRET-MARKER-498-hunter2-QX7"
private let controlMarker = "CONTROL-MARKER-498-visible-ZP3"

/// The columns of a secure row the tests look at (`Row` is not Sendable, so it cannot leave the read).
private struct SecureRow: Sendable {
    let isSecure: Int
    let kind: String
    let plainText: String?
    let searchText: String?
    let hotkeyCode: Int?
    let trigger: String?
    let contentKey: String
    let sourceName: String?
    let secureCiphertext: Data?
}

/// A capture wired like the app: real vault, real database, the database told about the same vault.
@MainActor
private final class SecureRig {
    let root: URL
    let database: FlotsamDatabase
    let pasteboard = ContractPasteboard()
    let keychain: MemoryKeychain
    let vault: SecureClipVault?
    let sink = RecordingSink()
    let presenter = FRD001RecordingPresenter()
    let reporter: ErrorReporter
    let capture: ClipboardCapture
    private var started = false
    var dataFolder: URL { root.appendingPathComponent("data") }

    init(withVault: Bool = true, keychain: MemoryKeychain = MemoryKeychain(), ignoring: Set<String> = []) async throws {
        root = FileManager.default.temporaryDirectory.appendingPathComponent("flotsam-498-capture-\(UUID().uuidString)")
        self.keychain = keychain
        let vault = withVault ? SecureClipVault(store: keychain) : nil
        self.vault = vault
        database = try await FlotsamDatabase.open(folder: root.appendingPathComponent("data"), secureVault: vault).get()
        let settings = SettingsStore(store: ContractKV())
        reporter = ErrorReporter(presenter: presenter, clock: ManualClock(), sink: sink)
        capture = ClipboardCapture(
            pasteboard: pasteboard, sourceApps: ContractSourceApps(frontmost: ContractRig.writerApp),
            ownWrites: OwnWriteLedger(), ingest: IngestActor(database: database, settings: settings), settings: settings,
            reporter: reporter, ignoredApps: { ignoring }, access: AllowedPasteboardAccess(), vault: vault, clock: ManualClock(),
            sink: sink, scheduleTimer: inertTimer)
    }

    func finish() async {
        await capture.stop()
        try? FileManager.default.removeItem(at: root)
    }

    /// Puts `representations` on the board and runs one capture to completion.
    func copy(_ representations: [PasteboardRepresentation]) async {
        pasteboard.copy(representations)
        // Started with the copy already on the board, so launch never reads an empty pasteboard (as OC-1004).
        if !started {
            capture.start()
            started = true
        }
        capture.captureNow()
        await capture.stop()
        capture.start()
        await quiesceReporter(reporter)
    }

    func copyConcealed(_ text: String, extra: [PasteboardRepresentation] = []) async {
        await copy(
            [PasteboardRepresentation(uti: PasteboardTypes.plainText, data: Data(text.utf8)),
             PasteboardRepresentation(uti: concealed, data: Data())] + extra)
    }

    func itemCount() async throws -> Int {
        try await database.pool.read { try Int.fetchOne($0, sql: "SELECT COUNT(*) FROM item")! }
    }

    func secureRow() async throws -> SecureRow? {
        try await database.pool.read { db in
            try Row.fetchOne(db, sql: "SELECT * FROM item WHERE isSecure = 1").map {
                SecureRow(
                    isSecure: $0["isSecure"], kind: $0["kind"], plainText: $0["plainText"], searchText: $0["searchText"],
                    hotkeyCode: $0["hotkeyCode"], trigger: $0["trigger"], contentKey: $0["contentKey"],
                    sourceName: $0["sourceName"], secureCiphertext: $0["secureCiphertext"])
            }
        }
    }

    /// Every file under the data folder (database, WAL, shared memory, blobs, thumbnails), as one byte string.
    func allDataBytes() -> Data {
        var all = Data()
        guard let walker = FileManager.default.enumerator(at: dataFolder, includingPropertiesForKeys: nil) else { return all }
        for case let url as URL in walker { all.append((try? Data(contentsOf: url)) ?? Data()) }
        return all
    }
}

private func contains(_ haystack: Data, _ needle: String) -> Bool { haystack.range(of: Data(needle.utf8)) != nil }

@MainActor
@Suite struct SecureCaptureTests {
    /// Guards `handleSecure` end to end: the concealed copy is stored as a secure row (no plain text, a ciphertext, a
    /// `secure:` content key), kept as text, with no other representation and no shortcut or trigger.
    @Test("AC-001-25: a concealed copy is stored as one secure row with ciphertext only")
    func concealedCopyBecomesASecureRow() async throws {
        let rig = try await SecureRig()
        await rig.copyConcealed(marker)

        #expect(try await rig.itemCount() == 1)
        let row = try #require(try await rig.secureRow())
        #expect(row.isSecure == 1)
        #expect(row.kind == "text")
        #expect(row.plainText == nil)
        #expect(row.searchText?.contains("writer") == true)  // the source app is searchable (FR-003-09); the text is not
        #expect(row.searchText?.lowercased().contains("hunter2") == false)
        #expect(row.hotkeyCode == nil)
        #expect(row.trigger == nil)
        #expect(row.contentKey.hasPrefix("secure:"))
        #expect(row.contentKey.count == 7 + 64)
        #expect(row.sourceName == "Writer")
        let ciphertext = try #require(row.secureCiphertext)
        #expect(try #require(rig.vault).open(ciphertext).get() == marker)
        #expect(try await rig.database.pool.read { try Int.fetchOne($0, sql: "SELECT COUNT(*) FROM representation")! } == 0)
        await rig.finish()
    }

    /// Guards the narrowed read in `ClipboardCapture` (`isConcealed ? [plainText] : typesToRead`): the board also holds
    /// HTML and RTF copies of the password, and neither is ever requested, let alone stored.
    @Test("AC-001-25: a concealed copy reads only the plain text, never the other representations")
    func concealedCopyReadsOnlyPlainText() async throws {
        let rig = try await SecureRig()
        await rig.copyConcealed(
            marker,
            extra: [
                PasteboardRepresentation(uti: PasteboardTypes.html, data: Data("<b>\(marker)</b>".utf8)),
                PasteboardRepresentation(uti: "public.rtf", data: Data("{\\rtf1 \(marker)}".utf8)),
            ])

        #expect(rig.pasteboard.bytesRequested == [PasteboardTypes.plainText])
        #expect(try await rig.itemCount() == 1)
        #expect(try await rig.database.pool.read { try Int.fetchOne($0, sql: "SELECT COUNT(*) FROM representation")! } == 0)
        #expect(contains(rig.allDataBytes(), "<b>") == false)
        await rig.finish()
    }

    /// The byte-grep of AC-001-25: the database, its WAL, shared memory and every blob, plus every log record (public and
    /// private text), hold no trace of the password. The control copy (not concealed) is found by the same grep, which
    /// proves the grep can see a stored text, so "absent" is a finding and not a blind spot.
    @Test("AC-001-25: no plaintext of a concealed copy in the database, its WAL or the log; a normal copy is found by the same grep")
    func noPlaintextAnywhere() async throws {
        let rig = try await SecureRig()
        await rig.copyConcealed(marker)
        await rig.copy([PasteboardRepresentation(uti: PasteboardTypes.plainText, data: Data(controlMarker.utf8))])

        #expect(try await rig.itemCount() == 2)
        let bytes = rig.allDataBytes()
        #expect(contains(bytes, controlMarker))
        #expect(contains(bytes, marker) == false)
        #expect(contains(bytes, "hunter2") == false)
        #expect(rig.sink.everything.contains(marker) == false)
        #expect(rig.sink.everything.contains("hunter2") == false)
        #expect(rig.sink.records.contains { $0.headline == "pasteboard.processed" })
        let ciphertext = try #require(try await rig.secureRow()?.secureCiphertext)
        #expect(bytes.range(of: ciphertext) != nil)  // the secure row's bytes are in the files the grep reads
        await rig.finish()
    }

    /// Guards the search index carrying nothing of the text: both the full text and a fragment find nothing, and the
    /// control copy is found, so an empty result is a finding.
    @Test("AC-001-25: search finds the normal copy and nothing of the concealed one")
    func searchDoesNotFindTheSecret() async throws {
        let rig = try await SecureRig()
        await rig.copyConcealed(marker)
        await rig.copy([PasteboardRepresentation(uti: PasteboardTypes.plainText, data: Data(controlMarker.utf8))])

        #expect(try await rig.database.count(filter: .all, text: "CONTROL-MARKER").get() == 1)
        #expect(try await rig.database.count(filter: .all, text: "SECRET-MARKER").get() == 0)
        #expect(try await rig.database.count(filter: .all, text: "hunter2").get() == 0)
        let rows = try await rig.database.items(matching: LibraryQuery(text: "")).get().rows
        #expect(rows.filter(\.isSecure).map(\.primaryLine) == ["\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}"])
        await rig.finish()
    }

    /// Guards the keyed fingerprint reaching `contentKey`: the same password again is one row copied twice (FR-001-15),
    /// another password is another row.
    @Test("AC-001-25: copying the same password again bumps one row; a different password adds one")
    func repeatedCopyBumps() async throws {
        let rig = try await SecureRig()

        await rig.copyConcealed(marker)
        await rig.copyConcealed(marker)
        #expect(try await rig.itemCount() == 1)
        #expect(try await rig.database.pool.read { try Int.fetchOne($0, sql: "SELECT copyCount FROM item")! } == 2)

        await rig.copyConcealed(marker + "-other")
        #expect(try await rig.itemCount() == 2)
        await rig.finish()
    }
}

@MainActor
@Suite struct SecureCaptureRejectionTests {
    /// Worf (TASK-498 QA), AC-008-06: the default list is empty, but a list the user fills in still wins over a password
    /// manager's concealed copy. Red if the ignored-apps gate (gate 4) is skipped for a concealed copy.
    @Test("AC-008-06 W498-I1: a concealed copy from an app the user ignores is rejected with CAP-POL-002 and stored nowhere")
    func concealedFromIgnoredAppIsRejected() async throws {
        let rig = try await SecureRig(ignoring: ["com.example.writer"])
        await rig.copyConcealed(marker)

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol002).count == 1)
        #expect(rig.sink.logged(.capPol001).count == 0)
        #expect(rig.pasteboard.bytesRequested.isEmpty)
        #expect(contains(rig.allDataBytes(), marker) == false)
        #expect(rig.sink.everything.contains(marker) == false)
        await rig.finish()
    }

    /// Control for the test above: the same copy with only a different app listed is stored, so CAP-POL-002 comes from
    /// the bundle id match and not from any non-empty list.
    @Test("AC-008-06 W498-I2: a concealed copy is stored when the ignored list names only other apps")
    func concealedFromANonIgnoredAppIsStored() async throws {
        let rig = try await SecureRig(ignoring: ["com.example.other"])
        await rig.copyConcealed(marker)

        #expect(try await rig.itemCount() == 1)
        #expect(rig.sink.logged(.capPol002).count == 0)
        #expect(try await rig.secureRow() != nil)
        await rig.finish()
    }

    /// Guards `vault == nil` in gate 3: with no vault a concealed copy fails closed exactly as it did before secure clips.
    @Test("AC-001-04: a concealed copy with no vault wired is rejected with CAP-POL-001 and nothing is stored")
    func noVaultRejectsConcealed() async throws {
        let rig = try await SecureRig(withVault: false)
        await rig.copyConcealed(marker)

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol001).count == 1)
        #expect(rig.pasteboard.bytesRequested.isEmpty)
        #expect(contains(rig.allDataBytes(), marker) == false)
        #expect(rig.sink.everything.contains(marker) == false)
        await rig.finish()
    }

    /// Guards `PasteboardMarkers.neverStoreAtCapture` still holding Transient and AutoGenerated, with the vault present.
    @Test("AC-001-04: Transient and AutoGenerated copies are still rejected with CAP-POL-001 when a vault is wired")
    func transientAndAutoGeneratedStillRejected() async throws {
        let rig = try await SecureRig()
        let text = PasteboardRepresentation(uti: PasteboardTypes.plainText, data: Data(controlMarker.utf8))

        await rig.copy([text, PasteboardRepresentation(uti: PasteboardMarkers.transient, data: Data())])
        await rig.copy([text, PasteboardRepresentation(uti: PasteboardMarkers.autoGenerated, data: Data())])

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol001).count == 2)
        #expect(rig.pasteboard.bytesRequested.isEmpty)
        await rig.finish()
    }

    /// Guards `!types.contains(plainText)` in gate 3: a concealed copy with only an image or a custom type has nothing
    /// safe to seal and is dropped, not stored in the clear through the ordinary path.
    @Test("AC-001-25: a concealed copy with no plain text is rejected and none of its data is read or stored")
    func concealedWithoutPlainTextIsRejected() async throws {
        let rig = try await SecureRig()
        await rig.copy([
            PasteboardRepresentation(uti: PasteboardTypes.html, data: Data("<i>\(marker)</i>".utf8)),
            PasteboardRepresentation(uti: concealed, data: Data()),
        ])

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol001).count == 1)
        #expect(rig.pasteboard.bytesRequested.isEmpty)
        #expect(contains(rig.allDataBytes(), marker) == false)
        await rig.finish()
    }

    /// Guards the whitespace check in `handleSecure`: an empty-looking password manager copy is not a secure item.
    @Test("AC-001-25: a concealed copy of only whitespace is rejected with CAP-POL-001 and nothing is stored")
    func whitespaceOnlyIsRejected() async throws {
        let rig = try await SecureRig()
        await rig.copyConcealed(" \n\t  ")

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol001).count == 1)
        await rig.finish()
    }

    /// Guards fail-closed sealing: with the Keychain unreadable, `seal` fails and the text is stored nowhere, not even
    /// as a normal item, and no key is written over the one that cannot be read.
    @Test("AC-001-25: when the key cannot be had, the concealed copy is dropped with CAP-POL-001 and stored nowhere")
    func sealFailureStoresNothing() async throws {
        let keychain = MemoryKeychain(unreadable: true)
        let rig = try await SecureRig(keychain: keychain)
        await rig.copyConcealed(marker)

        #expect(try await rig.itemCount() == 0)
        #expect(rig.sink.logged(.capPol001).count == 1)
        #expect(keychain.key == nil)
        #expect(contains(rig.allDataBytes(), marker) == false)
        #expect(rig.sink.everything.contains(marker) == false)
        await rig.finish()
    }

    /// The same rig stores an ordinary copy afterwards: the rejections above are about the concealed type, not a
    /// broken harness.
    @Test("AC-001-25: an ordinary copy on the same rig is still stored, so the rejections are not a dead harness")
    func ordinaryCopyStillStored() async throws {
        let rig = try await SecureRig()
        await rig.copy([PasteboardRepresentation(uti: PasteboardTypes.plainText, data: Data(controlMarker.utf8))])

        #expect(try await rig.itemCount() == 1)
        #expect(try await rig.secureRow() == nil)
        #expect(contains(rig.allDataBytes(), controlMarker))
        await rig.finish()
    }
}
